sys_script_fix.script:
// Nome da tabela que você quer consultar
var tableName = 'x_1489173_futebol_m2m_x_1489173_fu_sys_user'; // Altere para a tabela desejada, por exemplo 'task' ou outra.

// Nome do campo que identifica o usuário (por exemplo, 'opened_by', 'assigned_to', etc.)
var userField = 'sys_user'; // Altere conforme o campo relacionado ao usuário.

var ga = new GlideAggregate(tableName);
ga.addAggregate('COUNT'); // Conta os registros
ga.groupBy(userField); // Agrupa pelo campo do usuário
//ga.orderByAggregate('COUNT', 'DESC'); // Ordena pelos registros em ordem decrescente
ga.query();

var ranking = [];

// Coletar dados dos usuários e suas contagens
while (ga.next()) {
    var userSysId = ga.getValue(userField);
    var count = parseInt(ga.getAggregate('COUNT'), 10); // Obter a contagem como número

    var userName = '';
    var mobilePhone = '';

    if (userSysId) {
        var userGR = new GlideRecord('sys_user');
        if (userGR.get(userSysId)) {
            userName = userGR.getValue('name'); // Obter o nome do usuário
            mobilePhone = userGR.getValue('mobile_phone'); // Obter o nome do usuário
        }
    }

    ranking.push({
        user: userName,
        phone: mobilePhone,
        count: count
    });
}

// Ordenar os resultados pela contagem de registros em ordem decrescente
ranking.sort(function(a, b) {
    if (b.count !== a.count) {
        return b.count - a.count; // Ordena pela contagem (decrescente)
    }
    return a.user.localeCompare(b.user); // Ordena pelo nome (crescente)
});

// Exibir os dados ordenados
var hoje = new GlideDate();
var log = "====================== RANKING CAPA "+hoje+" ======================";

for (var i = 0; i < ranking.length; i++) {
    var entry = ranking[i];
    log += "\n Rank " + (i + 1) + ": " + entry.user + " (" + entry.phone + ") - " + entry.count;
}

gs.info(log);
